    assertEquals("totalLength:-9216 is a negative number. " + "The current batch size is 1024, " + "you can reduce the value by 'orc.row.batch.size'.", defaultBatchSizeException.getMessage());
    int batchSizeOne = 1;
    LongColumnVector batchSizeOneScratchlcv = new LongColumnVector(batchSizeOne);
    for (int i = 0; i < batchSizeOne; i++) {
        batchSizeOneScratchlcv.vector[i] = Long.MAX_VALUE;
    }
    BytesColumnVector batchSizeOneResult = new BytesColumnVector(batchSizeOne);
    IOException batchSizeOneException = assertThrows(IOException.class, () -> TreeReaderFactory.BytesColumnVectorUtil.readOrcByteArrays(stream, lengths, batchSizeOneScratchlcv, batchSizeOneResult, batchSizeOne));
    assertEquals("totalLength:-1 is a negative number.", batchSizeOneException.getMessage());
}

